@Service
public class LoanService {

    private final BookRepository books;
    private final LoanRepository loans;

    public LoanService(BookRepository books, LoanRepository loans) {
        this.books = books;
        this.loans = loans;
    }

    @Transactional
    public Loan borrow(Long bookId, Long memberId) {
        Book book = books.findById(bookId).orElseThrow(() -> new BookNotFound(bookId));
        if (book.getCopies() == 0) {
            throw new NoCopiesLeft(bookId);        // unchecked: rolls back
        }
        book.setCopies(book.getCopies() - 1);      // dirty checking
        return loans.save(new Loan(bookId, memberId));
    }

    @Transactional(readOnly = true)
    public List<Book> available() {
        return books.findByCopiesGreaterThan(0, Pageable.unpaged()).getContent();
    }
}

