@WebMvcTest(BookController.class)
class BookControllerTest {

    @Autowired MockMvc mvc;
    @MockitoBean BookService service;
    @Test
    void getReturnsBook() throws Exception {
        when(service.find(1L)).thenReturn(new BookResponse(1L, "Dune", "978-0", 2));

        mvc.perform(get("/api/books/1"))
           .andExpect(status().isOk())
           .andExpect(jsonPath("$.title", is("Dune")));
    }

    @Test
    void missingBookIs404() throws Exception {
        when(service.find(9L)).thenThrow(new BookNotFound(9L));

        mvc.perform(get("/api/books/9"))
           .andExpect(status().isNotFound());
    }

    @Test
    void invalidBodyIs400() throws Exception {
        mvc.perform(post("/api/books")
                .contentType(MediaType.APPLICATION_JSON)
                .content("{\"title\":\"\",\"isbn\":\"1\",\"copies\":-1}"))
           .andExpect(status().isBadRequest());
    }
}

