@SpringBootTest(webEnvironment = SpringBootTest.WebEnvironment.RANDOM_PORT)
class LibraryApiIT {

    @Autowired TestRestTemplate rest;

    @Test
    void createThenFetchBook() {
        var request = new CreateBookRequest("Dune", "978-0-441", 2);

        ResponseEntity<BookResponse> created =
            rest.postForEntity("/api/books", request, BookResponse.class);
        assertThat(created.getStatusCode()).isEqualTo(HttpStatus.CREATED);

        BookResponse fetched =
            rest.getForObject("/api/books/" + created.getBody().id(), BookResponse.class);
        assertThat(fetched.title()).isEqualTo("Dune");
    }
}

